const nextId = (prefix) => `${prefix}-${++uid}`;

/**
 * <x-tabs>
 *   <x-tab-panel label="Details">...</x-tab-panel>
 *   <x-tab-panel label="Settings">...</x-tab-panel>
 * </x-tabs>
 *
 * Builds a roving-tabindex tablist of buttons from the panels' `label`
 * attributes, wires up the full ARIA tabs pattern, activates on focus
 * (automatic activation), supports ArrowLeft/ArrowRight with wrap-around
 * plus Home/End, and reflects the active panel via `selected-index`.
 */
export class XTabs extends HTMLElement {
  static get observedAttributes() {
    return ['selected-index'];
  }

  #tablist = null;
  #observer = null;
  #applyingAttribute = false;

  connectedCallback() {
    this.#build();
    // Rebuild the tablist when panels are added/removed after connection.
    this.#observer = new MutationObserver((mutations) => {
      const relevant = mutations.some(
        (m) =>
          [...m.addedNodes, ...m.removedNodes].some(
            (n) => n.nodeType === 1 && n !== this.#tablist
          ) ||
          m.type === 'attributes'
      );
      if (relevant) this.refresh();
    });
    this.#observer.observe(this, { childList: true, attributes: true, attributeFilter: ['label'], subtree: false });

    if (!this.hasAttribute('selected-index')) {
      this.setAttribute('selected-index', String(this.#index));
    }
  }

  disconnectedCallback() {
    this.#observer?.disconnect();
    this.#observer = null;
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name !== 'selected-index' || oldValue === newValue || this.#applyingAttribute) return;
    const index = Number.parseInt(newValue ?? '0', 10);
    if (Number.isNaN(index)) return;
    this.#applySelection(index);
  }

  /** Currently selected panel index. Reflects to/from `selected-index`. */
  get selectedIndex() {
    return this.#index;
  }

  set selectedIndex(value) {
    const index = Number(value) | 0;
    this.setAttribute('selected-index', String(index));
  }

  /** Rebuild the tablist and re-derive selection (e.g. after DOM changes). */
  refresh() {
    this.#build();
  }

  /* ---- internals ---- */

  get #index() {
    const raw = this.getAttribute('selected-index');
    const parsed = Number.parseInt(raw ?? '0', 10);
    return Number.isNaN(parsed) ? 0 : parsed;
  }

  get #panels() {
    return [...this.querySelectorAll(':scope > x-tab-panel')];
  }

  #build() {
    const panels = this.#panels;
    const previous = this.#tablist;

    if (previous) {
      previous.remove();
      this.#tablist = null;
    }

    const tablist = document.createElement('div');
    tablist.setAttribute('role', 'tablist');
    this.#tablist = tablist;

    const tabs = panels.map((panel, i) => {
      if (!panel.id) panel.id = nextId('x-tab-panel');
      if (!panel.hasAttribute('role')) panel.setAttribute('role', 'tabpanel');

      const tab = document.createElement('button');
      tab.type = 'button';
      tab.id = nextId('x-tab');
      tab.setAttribute('role', 'tab');
      tab.textContent = panel.label;
      tab.setAttribute('aria-controls', panel.id);
      panel.setAttribute('aria-labelledby', tab.id);

      tab.addEventListener('click', () => this.#select(i));
      tablist.appendChild(tab);
      return tab;
    });

    tablist.addEventListener('keydown', (event) => this.#onKeydown(event));
    this.insertBefore(tablist, this.firstChild);

    this.#applySelection(Math.min(Math.max(this.#index, 0), Math.max(panels.length - 1, 0)), { tabs });
  }

  #select(index) {
    // Property setter path: reflect through the attribute.
    if (!this.#applyingAttribute) {
      this.selectedIndex = index;
      return; // attributeChangedCallback -> #applySelection
    }
    this.#applySelection(index);
  }

  #applySelection(index, { tabs } = {}) {
    const panels = this.#panels;
    if (tabs) this.#tabsCache = tabs;
    const tabEls = this.#tablist ? [...this.#tablist.querySelectorAll('[role="tab"]')] : [];

    this.#applyingAttribute = true;
    try {
      tabEls.forEach((tab, i) => {
        const selected = i === index;
        tab.setAttribute('aria-selected', String(selected));
        tab.tabIndex = selected ? 0 : -1;
        panels[i]?.toggleAttribute('hidden', !selected);
        panels[i]?.setAttribute('tabindex', '0');
      });
      this.#indexValue = index;
    } finally {
      this.#applyingAttribute = false;
    }
  }

  #indexValue = 0;
  #tabsCache = [];

  get selectedIndexCached() {
    return this.#indexValue;
  }

  #onKeydown(event) {
    const tablist = this.#tablist;
    if (!tablist) return;
    const tabs = [...tablist.querySelectorAll('[role="tab"]')];
    if (tabs.length === 0) return;

    const current = tabs.indexOf(event.target);
    if (current === -1) return;

    let next = null;
    switch (event.key) {
      case 'ArrowRight':
        next = (current + 1) % tabs.length; // wraps around
        break;
      case 'ArrowLeft':
        next = (current - 1 + tabs.length) % tabs.length; // wraps around
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = tabs.length - 1;
        break;
      default:
        return;
    }

    event.preventDefault();
    // Automatic activation: focusing a tab also selects it.
    tabs[next].focus();
    this.#select(next);
  }
}

