    if (name !== 'label' || oldValue === newValue) return;
    const tablist = this.parentElement?.querySelector?.(':scope > [role="tablist"]');
    const index = this.parentPanels().indexOf(this);
    const tab = tablist?.querySelectorAll('[role="tab"]')[index];
    if (tab) tab.textContent = this.label;
    this.parentElement?.refresh?.();
  }

  parentPanels() {
    return [...(this.parentElement?.querySelectorAll(':scope > x-tab-panel') ?? [])];
  }

  get label() {
    return this.getAttribute('label') ?? '';
  }

  set label(value) {
    this.setAttribute('label', value);
  }
}

