import { describe, it, expect, beforeEach } from 'vitest';
import { XTabs, XTabPanel } from '../src/x-tabs.js';

function makeTabs(count = 3) {
  const tabs = document.createElement('x-tabs');
  for (let i = 0; i < count; i++) {
    const panel = document.createElement('x-tab-panel');
    panel.setAttribute('label', `Panel ${i + 1}`);
    panel.textContent = `content ${i + 1}`;
    tabs.appendChild(panel);
  }
  document.body.appendChild(tabs);
  return tabs;
}

const tablistOf = (el) => el.querySelector('[role="tablist"]');
const tabsOf = (el) => [...tablistOf(el).querySelectorAll('[role="tab"]')];
const panelsOf = (el) => [...el.querySelectorAll(':scope > x-tab-panel')];

describe('<x-tabs>', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  it('builds a correct initial ARIA tree', () => {
    const el = makeTabs(3);

    const tablist = tablistOf(el);
    expect(tablist).toBeTruthy();
    expect(tablist.getAttribute('role')).toBe('tablist');

    const tabs = tabsOf(el);
    expect(tabs).toHaveLength(3);
    expect(panelsOf(el)).toHaveLength(3);

    tabs.forEach((tab, i) => {
      const panel = panelsOf(el)[i];
      expect(tab.tagName).toBe('BUTTON');
      expect(tab.getAttribute('role')).toBe('tab');
      expect(tab.textContent).toBe(`Panel ${i + 1}`);
      // aria-controls <-> id wiring
      expect(tab.getAttribute('aria-controls')).toBe(panel.id);
      expect(panel.getAttribute('aria-labelledby')).toBe(tab.id);
      expect(panel.getAttribute('role')).toBe('tabpanel');
    });

    // exactly one selected, roving tabindex
    expect(tabs.map((t) => t.getAttribute('aria-selected'))).toEqual(['true', 'false', 'false']);
    expect(tabs.map((t) => t.tabIndex)).toEqual([0, -1, -1]);

    // exactly one visible panel
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([false, true, true]);
  });

  it('ArrowRight moves selection and focus forward with automatic activation', () => {
    const el = makeTabs(3);
    const tabs = tabsOf(el);
    tabs[0].focus();
    tablistOf(el).dispatchEvent(
      new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true })
    );

    // focus moved (roving tabindex)
    expect(document.activeElement).toBe(tabs[1]);
    // and the tab was activated
    expect(tabs.map((t) => t.getAttribute('aria-selected'))).toEqual(['false', 'true', 'false']);
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([true, false, true]);
    expect(tabs.map((t) => t.tabIndex)).toEqual([-1, 0, -1]);
  });

  it('ArrowLeft moves backward and wraps around from first to last', () => {
    const el = makeTabs(3);
    const tabs = tabsOf(el);
    tabs[0].focus();
    tablistOf(el).dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowLeft' }));
    expect(document.activeElement).toBe(tabs[2]);
    expect(tabs[2].getAttribute('aria-selected')).toBe('true');
    expect(panelsOf(el)[2].hidden).toBe(false);
  });

  it('ArrowRight wraps around from last to first', () => {
    const el = makeTabs(3);
    el.selectedIndex = 2;
    const tabs = tabsOf(el);
    tabs[2].focus();
    tablistOf(el).dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight' }));
    expect(document.activeElement).toBe(tabs[0]);
    expect(tabs[0].getAttribute('aria-selected')).toBe('true');
    expect(panelsOf(el)[0].hidden).toBe(false);
  });

  it('Home jumps to the first tab, End to the last', () => {
    const el = makeTabs(4);
    const tabs = tabsOf(el);

    tabs[1].focus();
    tablistOf(el).dispatchEvent(new KeyboardEvent('keydown', { key: 'End' }));
    expect(document.activeElement).toBe(tabs[3]);
    expect(tabs[3].getAttribute('aria-selected')).toBe('true');
    expect(panelsOf(el)[3].hidden).toBe(false);

    tabs[3].focus();
    tablistOf(el).dispatchEvent(new KeyboardEvent('keydown', { key: 'Home' }));
    expect(document.activeElement).toBe(tabs[0]);
    expect(tabs[0].getAttribute('aria-selected')).toBe('true');
    expect(panelsOf(el)[0].hidden).toBe(false);
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([false, true, true, true]);
  });

  it('reflects attribute -> property -> DOM', () => {
    const el = makeTabs(3);
    el.setAttribute('selected-index', '2');

    expect(el.selectedIndex).toBe(2);
    const tabs = tabsOf(el);
    expect(tabs.map((t) => t.getAttribute('aria-selected'))).toEqual(['false', 'false', 'true']);
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([true, true, false]);
  });

  it('reflects property -> attribute -> DOM', () => {
    const el = makeTabs(3);
    el.selectedIndex = 1;

    expect(el.getAttribute('selected-index')).toBe('1');
    const tabs = tabsOf(el);
    expect(tabs.map((t) => t.getAttribute('aria-selected'))).toEqual(['false', 'true', 'false']);
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([true, false, true]);
  });

  it('rebuilds the tablist when a new panel is appended after connection', async () => {
    const el = makeTabs(2);
    expect(tabsOf(el)).toHaveLength(2);

    const panel = document.createElement('x-tab-panel');
    panel.setAttribute('label', 'Details');
    panel.textContent = 'details content';
    el.appendChild(panel);

    // MutationObserver callbacks run as microtasks; flush them.
    await Promise.resolve();

    const tabs = tabsOf(el);
    expect(tabs).toHaveLength(3);
    expect(tabs[2].textContent).toBe('Details');
    expect(tabs[2].getAttribute('role')).toBe('tab');
    expect(tabs[2].getAttribute('aria-controls')).toBe(panel.id);
    expect(panel.getAttribute('role')).toBe('tabpanel');

    // selection preserved on the previously selected index, ARIA tree consistent
    expect(tabs.map((t) => t.getAttribute('aria-selected'))).toEqual(['true', 'false', 'false']);
    expect(tabs.map((t) => t.tabIndex)).toEqual([0, -1, -1]);
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([false, true, true]);

    // keyboard still works on the rebuilt list
    tabs[2].focus();
    tablistOf(el).dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowLeft' }));
    expect(document.activeElement).toBe(tabs[1]);
    expect(tabs[1].getAttribute('aria-selected')).toBe('true');
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([true, false, true]);
  });

  it('clicking a tab selects it', () => {
    const el = makeTabs(3);
    tabsOf(el)[2].click();
    expect(el.selectedIndex).toBe(2);
    expect(panelsOf(el).map((p) => p.hidden)).toEqual([true, true, false]);
  });
});

describe('<x-tab-panel>', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  it('exposes its label via attribute/property both ways', () => {
    const panel = document.createElement('x-tab-panel');
    document.body.appendChild(panel);
    panel.label = 'Details';
    expect(panel.getAttribute('label')).toBe('Details');
    expect(panel.label).toBe('Details');
  });

  it('updates the tab button when label changes', async () => {
    const el = makeTabs(2);
    panelsOf(el)[1].setAttribute('label', 'Renamed');
    expect(tabsOf(el)[1].textContent).toBe('Renamed');
  });
});
"})
